      "section": "Introduction",
      "text": "C-squared is a configuration-dependent semi-empirical constant; its selection requires justification rather than a universal value copied from another assembly."
    }
  ],
  "case_packet": {
    "evidence": [
      {
        "evidence_id": "OBS-9700",
        "text": "The office social committee records the chosen cover image for the annual staff holiday greeting."
      },
      {
        "evidence_id": "OBS-2574",
        "text": "A force-limit draft sets C-squared to 5. The only basis is that an unrelated lightweight unit used that value. The current load/support characteristics and a comparability assessment are absent."
      },
      {
        "evidence_id": "OBS-9679",
        "text": "The reception visitor brochure describes the public sculpture garden beside the city museum."
      }
    ],
    "proposal": "Use the selected C-squared for this load/support configuration."
  },
  "allowed_request_ids": [
    "CONFIGURATION_SPECIFIC_C2_BASIS"
  ]
}

