{
  "review_question": "Does the proposal distinguish monitoring during stimulus from recovery after the test?",
  "claim_id": "CLM-EE02-P01",
  "reference_context": [
    {
      "reference_id": "SF-4015",
      "source_id": "EE-02",
      "printed_pages": [],
      "pdf_pages_1based": [
        14
      ],
      "section": "1.6 Pass/Fail criteria",
      "text": "The report evaluates channel data during interference injection against baseline data before and after testing, and examines response timing in relation to the applied sweep."
    }
  ],
  "case_packet": {
    "evidence": [
      {
        "evidence_id": "OBS-3955",
        "text": "The reception mail log records a packet of museum postcards addressed to the employee social club."
      },
      {
        "evidence_id": "OBS-2829",
        "text": "During an injected sweep, one monitored functional channel changes at the same time as the applied stimulus. Its post-test baseline returns to the pre-test value."
      },
      {
        "evidence_id": "OBS-6981",
        "text": "The staff walking-club calendar lists a weekend visit to a public botanical garden."
      }
    ],
    "proposal": "Retain the during-stimulus observation for investigation and record post-test recovery separately; the return to baseline does not erase the observation."
  },
  "allowed_request_ids": []
}

{
  "review_question": "Are the per-component thermal-model power inputs ready for the proposed correlation?",
  "claim_id": "CLM-005",
  "reference_context": [
    {
      "reference_id": "SF-5580",
      "source_id": "TH-01",
      "printed_pages": [
        "29",
        "62"
      ],
      "pdf_pages_1based": [
        38,
        71
      ],
      "section": "On-Site Thermal Support; Conclusions",
      "text": "Individual component power estimates were weakened by shared power buses and long measurement leads. The report emphasizes knowing both dissipation rates and heat-source locations for correlation."
    }
  ],
  "case_packet": {
    "evidence": [
      {
        "evidence_id": "OBS-2905",
        "text": "The staff book-club register lists a historical novel selected for the next monthly reading meeting."
      },
      {
        "evidence_id": "OBS-8120",
        "text": "Several thermal mockup units share a power bus. Electrical power is measured upstream of long leads. Only total bus input and commanded heater duties are available; per-unit dissipation and heat-deposition locations are absent."
      },
      {
        "evidence_id": "OBS-9692",
        "text": "The company art-club newsletter announces a watercolor exhibition at the local community gallery."
      }
    ],
    "proposal": "Initialize each component node with its own measured dissipation at the corresponding heat-source location."
  },
  "allowed_request_ids": [
    "PER_COMPONENT_POWER_AND_LOCATION"
  ]
}

{
