      },
      {
        "evidence_id": "OBS-4114",
        "text": "The employee history-club newsletter announces a walking tour of the old municipal market district."
      },
      {
        "evidence_id": "OBS-7010",
        "text": "The reception library catalog lists a donated collection of travel essays for staff leisure reading."
      }
